"""10. kor: 34 uj tura (koztuk 4 antarktiszi). Sorrend: add_r10 -> tours_order <r10_ids> -> dup_check -> poi_registry -> tours_kw -> tours_img -> tours_check"""
from tourlib import *
import json, os
C = lambda e, h: (e, h)
ES = C("Spain", "Spanyolország"); GB = C("United Kingdom", "Egyesült Királyság"); SE = C("Sweden", "Svédország"); IS = C("Iceland", "Izland"); TR = C("Turkey", "Törökország")
